import{_ as a,o as t,c as r,a4 as s}from"./chunks/framework.DUuHxaiX.js";const o="/smartycards/assets/deck-summary-report.CMzAnmCA.png",c="/smartycards/assets/deck-summary-report-on-cards.DmycYnhn.png",i="/smartycards/assets/summary-report-create-edit-cols.CJRe3ltX.png",n="/smartycards/assets/deck-summary-report-participation.N33otjwj.png",g=JSON.parse('{"title":"Deck Summary Report","description":"","frontmatter":{},"headers":[],"relativePath":"teaching/deck-summary-report.md","filePath":"teaching/deck-summary-report.md","lastUpdated":1768929607000}'),d={name:"teaching/deck-summary-report.md"};function l(h,e,m,p,u,k){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="deck-summary-report" tabindex="-1">Deck Summary Report <a class="header-anchor" href="#deck-summary-report" aria-label="Permalink to &quot;Deck Summary Report&quot;">​</a></h1><p><img src="'+o+'" alt="Access the deck summary report"></p><p>When faculty <a href="/smartycards/quick-start.html#create-a-deck">create</a> and <a href="/smartycards/sharing-decks.html">share</a> a deck with their class, they&#39;ll be able to see a Deck Summary report.</p><p>To access the report, go to <code>Your Deck &gt; Report</code>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Only Deck Owners can see the deck summary report. Editors and viewers do not have access.</p></div><h2 id="card-summary" tabindex="-1">Card Summary <a class="header-anchor" href="#card-summary" aria-label="Permalink to &quot;Card Summary&quot;">​</a></h2><p><img src="'+c+'" alt="Summary of average score and number of attempts for each card"></p><p>The report will show the <strong>average score</strong> and <strong>number of attempts</strong> for each card. This is calculated from the results of all practice sessions from <strong>all members</strong>.</p><p>This is a great way to see which concepts might need reviewing in class.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>How are the scores calculated?</strong> Each time a student practices a card, a score is recorded based on the icon they click</p><ul><li>✅ = 3 points</li><li>😕 = 2 points</li><li>❌ = 1 point</li></ul><p>The score in the summary report is the average of all attempts among all deck members.</p></div><h3 id="card-authorship-information" tabindex="-1">Card Authorship Information <a class="header-anchor" href="#card-authorship-information" aria-label="Permalink to &quot;Card Authorship Information&quot;">​</a></h3><p><img src="'+i+'" alt="Card authorship information in deck summary report"></p><p>Each card in the summary report displays authorship information:</p><ul><li><strong>Created by</strong> — The user who originally created the card and when it was created</li><li><strong>Last edited by</strong> — The user who most recently edited the card and when the edit was made</li></ul><p>This helps faculty track contributions when multiple editors collaborate on a deck, and provides context for when cards were last reviewed or updated.</p><h2 id="deck-participation" tabindex="-1">Deck Participation <a class="header-anchor" href="#deck-participation" aria-label="Permalink to &quot;Deck Participation&quot;">​</a></h2><p><img src="'+n+'" alt="summary report of deck member participation"></p><p>At the bottom of the report, you&#39;ll see a list of all members and which activities they&#39;ve participated in.</p><h3 id="✅-practiced-all-cards" tabindex="-1">✅ Practiced All Cards <a class="header-anchor" href="#✅-practiced-all-cards" aria-label="Permalink to &quot;✅ Practiced All Cards&quot;">​</a></h3><p>This is checked when a members has used <a href="/smartycards/activities/practice-flashcards.html">practice mode</a> on <strong>every</strong> card in the deck <strong>at least once</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Practice all cards updates when the deck updates. So, if new cards are added to the deck, a user won&#39;t regain their check mark until those new cards are practiced at least once.</p></div><h3 id="✅-quiz" tabindex="-1">✅ Quiz <a class="header-anchor" href="#✅-quiz" aria-label="Permalink to &quot;✅ Quiz&quot;">​</a></h3><p>This is checked when a user has tried the Quiz activity at least once.</p><p>Users only need to complete a single quiz. They do not need to be quizzed on every card to earn this checkmark.</p><h3 id="✅-matching-game" tabindex="-1">✅ Matching Game <a class="header-anchor" href="#✅-matching-game" aria-label="Permalink to &quot;✅ Matching Game&quot;">​</a></h3><p>Similar to Quiz mode, this is checked when a user has tried the Matching game activity at least once.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Interested in other reporting options, or Canvas integration? We want to hear more from you: what data is most useful to you and your students?</p><p>Email <a href="mailto:latistecharch@umn.edu" target="_blank" rel="noreferrer">latistecharch@umn.edu</a></p></div>',27)])])}const f=a(d,[["render",l]]);export{g as __pageData,f as default};
